import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.CqGPl1zp.js";const h=JSON.parse('{"title":"【其它】WMS、MES、ERP 对比","description":"","frontmatter":{},"headers":[],"relativePath":"wms/compare.md","filePath":"wms/compare.md","lastUpdated":null}'),c={name:"wms/compare.md"};function s(a,t,_,i,n,m){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="【其它】wms、mes、erp-对比" tabindex="-1">【其它】WMS、MES、ERP 对比 <a class="header-anchor" href="#【其它】wms、mes、erp-对比" aria-label="Permalink to &quot;【其它】WMS、MES、ERP 对比&quot;">​</a></h1><p>yudao 体系内 WMS、MES、ERP 三个模块都涉及&quot;库存&quot;与&quot;出入库单据&quot;，业务边界与技术深度差异较大。本文用一张总览表 + 几条选型建议，帮你判断当前业务该用哪个模块。</p><h2 id="_1-三者总览" tabindex="-1">1. 三者总览 <a class="header-anchor" href="#_1-三者总览" aria-label="Permalink to &quot;1. 三者总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>WMS</th><th>MES</th><th>ERP</th></tr></thead><tbody><tr><td>后端模块</td><td><code>yudao-module-wms</code></td><td><code>yudao-module-mes</code></td><td><code>yudao-module-erp</code></td></tr><tr><td>前端目录</td><td><code>@/views/wms</code></td><td><code>@/views/mes</code></td><td><code>@/views/erp</code></td></tr><tr><td>业务定位</td><td><strong>纯仓储管理</strong></td><td><strong>制造执行</strong>（生产 + 仓储 + 质量 + 设备）</td><td><strong>企业资源计划</strong>（采购 + 销售 + 库存 + 财务）</td></tr><tr><td>表数量</td><td>16 张</td><td>133 张</td><td>30+ 张</td></tr><tr><td>核心维度</td><td>仓库 + SKU</td><td>仓库 + 库区 + 库位 + 批次 + SN（五维聚合）</td><td>仓库 + 产品</td></tr><tr><td>单据形态</td><td>入 / 出 / 移 / 盘 4 类（共 8 张表）</td><td>10+ 类（采购入库、销售出库、生产领退料、外协…）</td><td>采购订单 → 入库 / 退货、销售订单 → 出库 / 退货等</td></tr><tr><td>库存事务</td><td><strong>统一服务</strong>（<code>changeInventory</code> / <code>checkInventory</code>）</td><td>库存事务 + 虚拟线边库 + 主子表批次拆分</td><td>直接在各单据 Service 内变更</td></tr><tr><td>上下游</td><td>不联动</td><td>关联工序 / 工单 / 质检 / 设备</td><td>关联供应商付款 / 客户收款</td></tr><tr><td>适合企业</td><td>仅需&quot;管库存进出&quot;的中小仓储</td><td>离散制造业全链路落地</td><td>销售型企业（电商 / 零售 等）</td></tr></tbody></table><h2 id="_2-模块能力地图" tabindex="-1">2. 模块能力地图 <a class="header-anchor" href="#_2-模块能力地图" aria-label="Permalink to &quot;2. 模块能力地图&quot;">​</a></h2><h3 id="_2-1-wms" tabindex="-1">2.1 WMS <a class="header-anchor" href="#_2-1-wms" aria-label="Permalink to &quot;2.1 WMS&quot;">​</a></h3><p>只做仓储管理，3 大块：</p><ul><li><strong>基础数据</strong>：仓库、商品（含 SKU / 分类 / 品牌）、往来企业（供应商 / 客户）。</li><li><strong>库存台账</strong>：库存记录 + 库存流水 + 库存事务。</li><li><strong>业务单据</strong>：入库（采购 / 生产 / 退货 / 归还）、出库（销售 / 退货 / 生产）、移库（仓间转移）、盘库（差异调整）。</li></ul><p><strong>不涉及</strong>：采购订单 / 销售订单 / 应收应付 / 财务结算 / 生产工单 / 工序工艺 / 质检 / 设备 / 工具 / 排班；也<strong>不涉及</strong>库区库位、批次、生产日期、过期日期、SN 一物一码（详见 <a href="./build">《功能开启》</a>）。</p><p>详见 <a href="./../wms-preview">《WMS 演示》</a>。</p><h3 id="_2-2-mes" tabindex="-1">2.2 MES <a class="header-anchor" href="#_2-2-mes" aria-label="Permalink to &quot;2.2 MES&quot;">​</a></h3><p>制造执行系统，覆盖 7 大模块：</p><ul><li><strong>基础数据</strong>：物料、客户 / 供应商、车间、工作站、编码规则。</li><li><strong>生产管理</strong>：工序、工艺、工单、排产、报工、安灯。</li><li><strong>仓库管理</strong>（最重）：62 张表。仓库 → 库区 → 库位三级结构、批次管理、SN 码、虚拟线边库、到货通知、采购入库 / 退货、生产领退料 / 物料消耗、产品产出 / 入库、销售发货 / 出库 / 退货、外协发料 / 入库、调拨装箱、盘点等。</li><li><strong>质量管理</strong>：IQC / IPQC / OQC / RQC 四类质检 + 检测项 + 缺陷管理。</li><li><strong>设备管理</strong>：设备台账、点检保养、维修单。</li><li><strong>工具管理</strong>：工装夹具台账。</li><li><strong>排班管理</strong>：班组、排班计划、排班日历。</li></ul><p>详见 <a href="./../mes-preview">《MES 手册》</a>。</p><h3 id="_2-3-erp" tabindex="-1">2.3 ERP <a class="header-anchor" href="#_2-3-erp" aria-label="Permalink to &quot;2.3 ERP&quot;">​</a></h3><p>企业资源计划，5 大模块：</p><ul><li><strong>产品管理</strong>：产品信息、分类、单位。</li><li><strong>采购管理</strong>：采购订单 → 采购入库 / 退货。</li><li><strong>销售管理</strong>：销售订单 → 销售出库 / 退货。</li><li><strong>库存管理</strong>：产品库存、库存明细、其它入 / 出库、库存调拨、库存盘点。</li><li><strong>财务管理</strong>：采购付款、销售收款。</li></ul><p>详见 <a href="./../erp-preview">《ERP 手册》</a>。</p><h2 id="_3-选型建议" tabindex="-1">3. 选型建议 <a class="header-anchor" href="#_3-选型建议" aria-label="Permalink to &quot;3. 选型建议&quot;">​</a></h2><p>简单分流：</p><ul><li><strong>只管库存进出</strong>（仓储型公司、电商仓、生产辅料仓）→ <strong>WMS</strong>。开箱可用，结构最轻。</li><li><strong>需要采购订单 / 销售订单 / 应收应付 / 财务对账</strong>（销售型企业，如电商 / 零售）→ <strong>ERP</strong>。WMS 不带这套。</li><li><strong>离散制造业上下游全链路</strong>（带工艺、工单、报工、质检、设备）→ <strong>MES</strong>。覆盖最广，但学习成本最高。</li></ul><p>边界场景：</p><ul><li><strong>既要 WMS 的轻量仓储 + ERP 的销售订单链路</strong>：当前 yudao 没提供&quot;WMS + ERP 联动包&quot;。临时方案是各开各的模块，业务系统内手动同步主数据；后续如有官方联动需求请提 Issue。</li><li><strong>需要批次 / 库位 / SN 一物一码</strong>：当前 WMS <strong>不支持</strong>，请评估是否切换到 MES（MES 仓库管理模块原生支持）。</li><li><strong>库存口径要&quot;按月 / 按品类&quot;做财务结算</strong>：WMS 库存流水保留单价 + 金额字段（每笔变更都记），但<strong>不提供</strong>结算报表。需要的话可基于 <code>wms_inventory_history</code> 自建报表，或切换到 ERP。</li></ul><h2 id="_4-库存模型对比" tabindex="-1">4. 库存模型对比 <a class="header-anchor" href="#_4-库存模型对比" aria-label="Permalink to &quot;4. 库存模型对比&quot;">​</a></h2><p>三者库存的核心维度差异最大，单独对比一下。</p><h3 id="_4-1-维度与能力" tabindex="-1">4.1 维度与能力 <a class="header-anchor" href="#_4-1-维度与能力" aria-label="Permalink to &quot;4.1 维度与能力&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>WMS</th><th>MES</th><th>ERP</th></tr></thead><tbody><tr><td>聚合粒度</td><td><code>仓库 + SKU</code></td><td><code>仓库 + 库区 + 库位 + 物料 + 批次</code></td><td><code>仓库 + 产品</code></td></tr><tr><td>物料抽象</td><td>商品 + SKU 两级（SKU 含尺寸/重量/价格）</td><td>物料 + 批次属性 +（库位、SN）等多维</td><td>产品（单级，无 SKU）</td></tr><tr><td>明细 / 拆分表</td><td>不支持</td><td>有 <code>mes_wm_material_stock_detail</code>（5 维拆分）</td><td>不支持</td></tr><tr><td>虚拟仓</td><td>不支持</td><td>内置 <code>WIP_VIRTUAL_WAREHOUSE</code> 线边库</td><td>不支持</td></tr><tr><td>SN 序列号</td><td><strong>不支持</strong></td><td>支持（按批次批量生成、可分组管理 / 导出）</td><td><strong>不支持</strong></td></tr><tr><td>批次属性</td><td><strong>不支持</strong></td><td>支持生产日期、过期日期、到期提醒</td><td><strong>不支持</strong></td></tr><tr><td>写入路径</td><td>统一服务 2 个核心方法</td><td>事务服务（细分类型：外协、生产消耗、归还等）</td><td><code>ErpStockRecordService</code> 由各单据 Service 直接调用</td></tr><tr><td>出入两阶段</td><td>草稿 → 已完成 / 已作废</td><td>多状态（草稿 → 待上架 → 待执行入库 → 已完成 等）</td><td><strong>无两阶段</strong>，单据直接出入</td></tr></tbody></table><p>如果业务确实需要批次 / 库位 / SN 这套精细化库存管理，建议<strong>直接选 MES</strong>，不要在 WMS / ERP 上自行扩展。</p><h3 id="_4-2-相关表映射" tabindex="-1">4.2 相关表映射 <a class="header-anchor" href="#_4-2-相关表映射" aria-label="Permalink to &quot;4.2 相关表映射&quot;">​</a></h3><p>按角色对齐 WMS / MES / ERP 同类表，便于跨模块迁移时一一对照：</p><table tabindex="0"><thead><tr><th>角色 / 概念</th><th>WMS</th><th>MES</th><th>ERP</th></tr></thead><tbody><tr><td>库存主表</td><td><code>wms_inventory</code></td><td><code>mes_wm_material_stock</code></td><td><code>erp_stock</code></td></tr><tr><td>库存流水</td><td><code>wms_inventory_history</code></td><td><code>mes_wm_transaction</code></td><td><code>erp_stock_record</code></td></tr><tr><td>仓库</td><td><code>wms_warehouse</code></td><td><code>mes_wm_warehouse</code>（+ <code>_area</code> + <code>_location</code> 三级）</td><td><code>erp_warehouse</code></td></tr><tr><td>物料 / 商品</td><td><code>wms_item</code> + <code>wms_item_sku</code></td><td><code>mes_md_item</code>（+ <code>mes_wm_batch</code> 等扩展）</td><td><code>erp_product</code></td></tr><tr><td>商品分类</td><td><code>wms_item_category</code></td><td><code>mes_md_item_type</code></td><td><code>erp_product_category</code></td></tr><tr><td>商品品牌</td><td><code>wms_item_brand</code></td><td>—（无独立品牌维度）</td><td>—</td></tr><tr><td>供应商</td><td><code>wms_merchant</code>（<code>type = 2 / 3</code>）</td><td><code>mes_md_vendor</code></td><td><code>erp_supplier</code></td></tr><tr><td>客户</td><td><code>wms_merchant</code>（<code>type = 1 / 3</code>）</td><td><code>mes_md_client</code></td><td><code>erp_customer</code></td></tr><tr><td>入库单</td><td><code>wms_receipt_order</code> + <code>_detail</code></td><td><code>mes_wm_item_receipt</code> + <code>_line</code> + <code>_detail</code></td><td><code>erp_stock_in</code> + <code>_item</code> / <code>erp_purchase_in*</code></td></tr><tr><td>出库单</td><td><code>wms_shipment_order</code> + <code>_detail</code></td><td>（销售出库 / 生产消耗 等多张单据）</td><td><code>erp_stock_out</code> + <code>_item</code> / <code>erp_sale_out*</code></td></tr><tr><td>移库 / 调拨</td><td><code>wms_movement_order</code> + <code>_detail</code></td><td><code>mes_wm_transfer</code></td><td><code>erp_stock_move</code> + <code>_item</code></td></tr><tr><td>盘库</td><td><code>wms_check_order</code> + <code>_detail</code></td><td><code>mes_wm_stock_taking_plan</code> + <code>_task</code> + 多张子表</td><td><code>erp_stock_check</code> + <code>_item</code></td></tr></tbody></table><blockquote><p>WMS 的&quot;往来企业&quot;是一表两用（<code>wms_merchant</code> 通过 <code>type</code> 区分客户 / 供应商），MES 和 ERP 都是<strong>客户、供应商分两张表</strong>。如果业务里&quot;客户/供应商&quot;经常重叠（如外协厂商），WMS 的设计更省事。</p></blockquote><h3 id="_4-3-mes-erp-的扩展能力" tabindex="-1">4.3 MES / ERP 的扩展能力 <a class="header-anchor" href="#_4-3-mes-erp-的扩展能力" aria-label="Permalink to &quot;4.3 MES / ERP 的扩展能力&quot;">​</a></h3><p>WMS 聚焦&quot;管库存进出&quot;，以下能力 WMS <strong>不涉及</strong>，从 WMS 切换到 MES / ERP 即可获得：</p><table tabindex="0"><thead><tr><th>能力</th><th>MES（仓储 / 制造侧）</th><th>ERP（销售 / 采购 / 财务侧）</th></tr></thead><tbody><tr><td>三级仓库（库区 / 库位）</td><td><code>mes_wm_warehouse_area</code> + <code>mes_wm_warehouse_location</code></td><td>—</td></tr><tr><td>批次（生产日期 / 过期日期 / 提醒）</td><td><code>mes_wm_batch</code> + <code>mes_md_item_batch_config</code></td><td>—</td></tr><tr><td>SN 一物一码</td><td><code>mes_wm_sn</code></td><td>—</td></tr><tr><td>条码赋码</td><td><code>mes_wm_barcode</code> + <code>mes_wm_barcode_config</code></td><td>—</td></tr><tr><td>到货 / 发货通知（预约）</td><td><code>mes_wm_arrival_notice*</code> + <code>mes_wm_sales_notice*</code></td><td>—（采购 / 销售订单直串入 / 出库）</td></tr><tr><td>上架明细（按库位 PutAway）</td><td><code>mes_wm_item_receipt_detail</code></td><td>—</td></tr><tr><td>装箱管理</td><td><code>mes_wm_package</code> + <code>_line</code></td><td>—</td></tr><tr><td>生产领退料 / 物料消耗</td><td><code>mes_wm_item_consume*</code> + <code>mes_wm_product_issue*</code></td><td>—</td></tr><tr><td>产品产出 / 入库</td><td><code>mes_wm_product_produce*</code> + <code>mes_wm_product_receipt*</code></td><td>—</td></tr><tr><td>外协发料 / 入库</td><td><code>mes_wm_outsource_issue*</code> + <code>mes_wm_outsource_receipt*</code></td><td>—</td></tr><tr><td>退货系列</td><td><code>mes_wm_return_issue*</code> / <code>_sales*</code> / <code>_vendor*</code></td><td><code>erp_purchase_return</code> + <code>_items</code> / <code>erp_sale_return</code> + <code>_items</code></td></tr><tr><td>编码规则（自动编号）</td><td><code>mes_md_auto_code_rule</code> / <code>_part</code> / <code>_record</code></td><td>—</td></tr><tr><td>BOM / SIP / SOP</td><td><code>mes_md_product_bom</code> / <code>_sip</code> / <code>_sop</code></td><td>—</td></tr><tr><td>计量单位</td><td><code>mes_md_unit_measure</code></td><td><code>erp_product_unit</code></td></tr><tr><td>采购订单链</td><td>—（依赖到货通知串联）</td><td><code>erp_purchase_order</code> + <code>_items</code> → <code>erp_purchase_in</code> + <code>_items</code></td></tr><tr><td>销售订单链</td><td>—（依赖发货通知串联）</td><td><code>erp_sale_order</code> + <code>_items</code> → <code>erp_sale_out</code> + <code>_items</code></td></tr><tr><td>财务付款（采购）</td><td>—</td><td><code>erp_finance_payment</code> + <code>_item</code></td></tr><tr><td>财务收款（销售）</td><td>—</td><td><code>erp_finance_receipt</code> + <code>_item</code></td></tr><tr><td>资金账户</td><td>—</td><td><code>erp_account</code></td></tr></tbody></table><blockquote><p>MES 仓储域共 <strong>62 张表</strong>，本表只列与 WMS 形成直接对比的关键扩展能力；质量管理 <code>mes_qc_*</code>、设备管理 <code>mes_dv_*</code>、生产 / 工艺 / 工单 <code>mes_pro_*</code>、排班 <code>mes_cal_*</code> 与&quot;库存&quot;无直接耦合，不在本表展开（详见 <a href="#_2-2-mes">§2.2 MES</a>）。</p></blockquote><h2 id="_5-落地步骤参考" tabindex="-1">5. 落地步骤参考 <a class="header-anchor" href="#_5-落地步骤参考" aria-label="Permalink to &quot;5. 落地步骤参考&quot;">​</a></h2><ul><li>选 WMS：参考 <a href="./build">《功能开启》</a>，3 分钟开起来；后续按 <a href="./../wms-preview">《WMS 演示》</a> 的 5 节表结构按需读模块文档。</li><li>选 MES：参考 <a href="./../mes/build">《MES 手册 —— 功能开启》</a>。</li><li>选 ERP：参考 <a href="./../erp/build">《ERP 手册 —— 功能开启》</a>。</li></ul>',38)])])}const p=d(c,[["render",s]]);export{h as __pageData,p as default};
